import React from 'react';

interface AnalyticsData {
  views: number;
  conversions: number;
  bounceRate: string;
}

interface Notification {
  id: number;
  message: string;
  isRead: boolean;
}

interface SettingsData {
  theme: string;
  emailNotifications: boolean;
  version: string;
}

interface DashboardData {
  analytics: AnalyticsData;
  notifications: Notification[];
  settings: SettingsData;
}

async function getDashboardData(): Promise<DashboardData> {
  try {
    // Fetch data in parallel as requested
    const [analytics, notifications, settings] = await Promise.all([
      fetch('http://localhost:3000/api/analytics').then((res) => res.json()),
      fetch('http://localhost:3000/api/notifications').then((res) => res.json()),
      fetch('http://localhost:3000/api/settings').then((res) => res.json()),
    ]);

    return { analytics, notifications, settings };
  } catch (error) {
    console.warn('Failed to fetch dashboard data, using mock data:', error);
    // Return mock data if fetch fails (following established pattern in page.tsx)
    return {
      analytics: {
        views: 12500,
        conversions: 450,
        bounceRate: '42%',
      },
      notifications: [
        { id: 1, message: 'System update scheduled', isRead: false },
        { id: 2, message: 'New user registration', isRead: true },
        { id: 3, message: 'Server load warning', isRead: false },
      ],
      settings: {
        theme: 'dark',
        emailNotifications: true,
        version: '1.0.0',
      },
    };
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData();

  return (
    <div className="p-4 border rounded-lg shadow-sm">
      <h2 className="text-2xl font-bold mb-4">Dashboard Overview</h2>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {/* Analytics Section */}
        <div className="p-4 border rounded bg-gray-50 dark:bg-gray-800">
          <h3 className="text-xl font-semibold mb-2">Analytics</h3>
          <ul className="space-y-2">
            <li>Views: <span className="font-mono">{analytics.views.toLocaleString()}</span></li>
            <li>Conversions: <span className="font-mono">{analytics.conversions}</span></li>
            <li>Bounce Rate: <span className="font-mono">{analytics.bounceRate}</span></li>
          </ul>
        </div>

        {/* Notifications Section */}
        <div className="p-4 border rounded bg-gray-50 dark:bg-gray-800">
          <h3 className="text-xl font-semibold mb-2">Notifications</h3>
          {notifications.length > 0 ? (
            <ul className="space-y-2">
              {notifications.map((notif) => (
                <li key={notif.id} className={`text-sm ${notif.isRead ? 'text-gray-500' : 'font-medium'}`}>
                  • {notif.message}
                </li>
              ))}
            </ul>
          ) : (
            <p className="text-gray-500">No new notifications</p>
          )}
        </div>

        {/* Settings Section */}
        <div className="p-4 border rounded bg-gray-50 dark:bg-gray-800">
          <h3 className="text-xl font-semibold mb-2">Settings</h3>
          <ul className="space-y-2">
            <li>Theme: <span className="capitalize">{settings.theme}</span></li>
            <li>Email Alerts: {settings.emailNotifications ? 'On' : 'Off'}</li>
            <li>Version: {settings.version}</li>
          </ul>
        </div>
      </div>
    </div>
  );
}

